const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");
const shared = ["vendor/domain-parser.js", "core/site-context.js", "core/settings.js", "core/diagnostics.js", "core/playback-policy.js", "adapters/page-context.js"];
const bundles = Object.freeze({
  "dist/main.js": [...shared, "core/media-policy.js", "core/media-evidence.js", "adapters/media-source.js", "adapters/player-dom.js", "adapters/visibility-playback.js", "adapters/youtube-channel.js", "content_main.js"],
  "dist/content.js": [...shared, "adapters/settings-store.js", "content.js"],
});

function renderBundle(files) {
  const source = files.map((file) => {
    const text = fs.readFileSync(path.join(root, file), "utf8").replace(/\r\n?/g, "\n").trimEnd();
    return `// Source: ${file}\n${text}`;
  }).join("\n\n");
  // Each world gets a distinct file and its own private lexical scope.
  return `// Generated by node scripts/build.cjs. Edit the source modules instead.\n(() => {\n"use strict";\n\n${source}\n})();\n`;
}

function build(check = false) {
  let current = true;
  const vendorPath = path.join(root, "vendor/domain-parser.js");
  const license = fs.readFileSync(path.join(root, "node_modules/tldts/LICENSE"), "utf8").trim();
  const parser = fs.readFileSync(path.join(root, "node_modules/tldts/dist/index.cjs.min.js"), "utf8")
    .replace(/^\/\/# sourceMappingURL=.*$/gm, "").trim();
  const vendor = `/* tldts 7.5.1 — MIT\n${license}\n*/\nconst YTAPDomainParser = (() => {\nconst exports = {};\n${parser}\nreturn Object.freeze(exports);\n})();\n`;
  const actualVendor = fs.existsSync(vendorPath) ? fs.readFileSync(vendorPath, "utf8").replace(/\r\n?/g, "\n") : null;
  if (actualVendor !== vendor.replace(/\r\n?/g, "\n")) {
    if (check) { console.error("vendor/domain-parser.js is stale; run npm run build"); current = false; }
    else { fs.mkdirSync(path.dirname(vendorPath), { recursive: true }); fs.writeFileSync(vendorPath, vendor.replace(/\r\n?/g, "\n")); }
  }
  for (const [output, inputs] of Object.entries(bundles)) {
    const target = path.join(root, output);
    const expected = renderBundle(inputs);
    const actual = fs.existsSync(target) ? fs.readFileSync(target, "utf8").replace(/\r\n?/g, "\n") : null;
    if (actual === expected) continue;
    if (check) {
      console.error(`${output} is stale; run node scripts/build.cjs`);
      current = false;
    } else {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, expected, "utf8");
    }
  }
  return current;
}

if (require.main === module && !build(process.argv.includes("--check"))) process.exitCode = 1;
module.exports = { bundles, renderBundle, build };
